import { useEffect, useState } from 'react';
import { Paper, Text, Title } from '@mantine/core';
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import axiosInstance from '../../utils/axiosInstance';
export default function DailyReviewTrend(){const[points,setPoints]=useState<Record<string,string|number>[]>([]);useEffect(()=>{void axiosInstance.get('/reviews/archive/trends',{params:{days:90}}).then(response=>{const byDate=new Map<string,Record<string,string|number>>();for(const snapshot of response.data.snapshots as Array<{snapshotDate:string;platform:string;sourceTotalCount:number|null;activeCount:number}>){const point:Record<string,string|number>=byDate.get(snapshot.snapshotDate)??{date:snapshot.snapshotDate};point[snapshot.platform]=snapshot.sourceTotalCount??snapshot.activeCount;byDate.set(snapshot.snapshotDate,point)}setPoints(Array.from(byDate.values()))})},[]);return <Paper p="lg" withBorder radius="lg"><Title order={4}>Daily review totals</Title><Text size="sm" c="dimmed" mb="md">Saved once per day when a platform syncs. History starts with this release.</Text>{points.length?<ResponsiveContainer width="100%" height={280}><LineChart data={points}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="date"/><YAxis allowDecimals={false}/><Tooltip/><Legend/><Line type="monotone" dataKey="google" stroke="#4285f4" connectNulls/><Line type="monotone" dataKey="tripadvisor" stroke="#00aa6c" connectNulls/><Line type="monotone" dataKey="airbnb" stroke="#ff385c" connectNulls/><Line type="monotone" dataKey="getyourguide" stroke="#ff5533" connectNulls/></LineChart></ResponsiveContainer>:<Text c="dimmed" ta="center" py="xl">Sync a platform to create the first daily snapshot.</Text>}</Paper>}
